import { readFile } from 'node:fs/promises';
import coffeescript from 'coffeescript';
import esbuild from 'esbuild';
import { expect, test } from 'vitest';
import coffeeScriptPlugin from '../src/index';

const decode = (result: esbuild.BuildResult) =>
  new TextDecoder().decode(result.outputFiles?.[0].contents);

test('expects importing CoffeeScript to work', async () => {
  const result = await esbuild.build({
    entryPoints: ['test/input/main.coffee'],
    plugins: [coffeeScriptPlugin({ bare: true })],
    write: false,
  });

  const mainCoffeeFile = await readFile('test/input/main.coffee', 'utf8');
  const coffee = coffeescript.compile(mainCoffeeFile, { bare: true });

  expect(result.outputFiles).toHaveLength(1);
  expect(decode(result).replace(/\n/g, '')).toContain(
    coffee.replace(/\n/g, '')
  );
});

test('compiles .litcoffee', async () => {
  const result = await esbuild.build({
    entryPoints: ['test/input/main.litcoffee'],
    plugins: [coffeeScriptPlugin({ bare: true, literate: true })],
    write: false,
  });

  expect(decode(result)).toContain(
    // biome-ignore lint/suspicious/noTemplateCurlyInString: Testing string
    'console.log(`the answer is ${answer}`);'
  );
});

test('works with requires when used with commonjs plugin', async () => {
  const result = await esbuild.build({
    bundle: true,
    entryPoints: ['test/input/import-class/main.coffee'],
    plugins: [coffeeScriptPlugin({ bare: true })],
    write: false,
    format: 'esm',
  });

  expect(decode(result)).toContain('A2 = class A');
});

test('throw on syntax error', async () => {
  await expect(
    esbuild.build({
      bundle: true,
      entryPoints: ['test/input/invalid-coffee.coffee'],
      plugins: [coffeeScriptPlugin({ bare: true })],
      write: false,
      logLevel: 'silent',
    })
  ).rejects.toThrow('Build failed with 1 error');
});

test('compiles with default options (no args)', async () => {
  const result = await esbuild.build({
    entryPoints: ['test/input/main.coffee'],
    plugins: [coffeeScriptPlugin()],
    write: false,
  });

  const output = decode(result);
  expect(output).toContain('(function() {');
});

test('bare: false wraps output in IIFE', async () => {
  const result = await esbuild.build({
    entryPoints: ['test/input/main.coffee'],
    plugins: [coffeeScriptPlugin({ bare: false })],
    write: false,
  });

  const output = decode(result);
  expect(output).toContain('(function() {');
});

test('header: true passes option to CoffeeScript compiler', async () => {
  const source = await readFile('test/input/main.coffee', 'utf8');
  const withHeader = coffeescript.compile(source, {
    bare: true,
    header: true,
  });
  const withoutHeader = coffeescript.compile(source, { bare: true });

  expect(withHeader).toContain('Generated by CoffeeScript');
  expect(withoutHeader).not.toContain('Generated by CoffeeScript');
});

test('inlineMap: true produces source map in output', async () => {
  const result = await esbuild.build({
    entryPoints: ['test/input/main.coffee'],
    plugins: [coffeeScriptPlugin({ bare: true, inlineMap: true })],
    write: false,
    sourcemap: 'inline',
  });

  expect(decode(result)).toContain(
    '//# sourceMappingURL=data:application/json;base64,'
  );
});

test('compiles .litcoffee without explicit literate option', async () => {
  const result = await esbuild.build({
    entryPoints: ['test/input/main.litcoffee'],
    plugins: [coffeeScriptPlugin({ bare: true })],
    write: false,
  });

  expect(decode(result)).toContain(
    // biome-ignore lint/suspicious/noTemplateCurlyInString: Testing string
    'console.log(`the answer is ${answer}`);'
  );
});

test('error contains accurate location information', async () => {
  try {
    await esbuild.build({
      entryPoints: ['test/input/invalid-coffee.coffee'],
      plugins: [coffeeScriptPlugin()],
      write: false,
      logLevel: 'silent',
    });
    expect.fail('Expected build to throw');
  } catch (e) {
    const error = (e as esbuild.BuildFailure).errors[0];
    expect(error.location).toBeDefined();
    expect(error.location?.line).toBe(0);
    expect(error.location?.column).toBe(8);
    expect(error.location?.lineText).toBe('hello . 8');
  }
});
